/**
 * Outlet service — tenant-scoped CRUD for outlets.
 * Verified against backend outlets controller + DTOs.
 *
 *  - GET    /outlets      → { success, data: Outlet[], meta } (paginated)
 *  - GET    /outlets/:id  → { success, data: Outlet }
 *  - POST   /outlets      → { name, address?, phone? }  (code is generated by backend)
 *  - PUT    /outlets/:id  → { name?, address?, phone?, isActive? }
 *  - DELETE /outlets/:id  → soft-delete (409 when in use)
 *
 * NOTE: `list` is also consumed by the Users module (outlet-assignment picker),
 * so its signature/return shape must remain backward compatible.
 */

import { httpClient } from './http'

interface ApiSuccess<T> {
  success: true
  message?: string
  data: T
}

interface ListMeta {
  page: number
  limit: number
  total: number
  totalPages: number
}

interface ApiListResponse<T> {
  success: true
  data: T[]
  meta: ListMeta
}

export interface Outlet {
  id: string
  companyId: string | null
  code: string
  name: string
  address: string | null
  phone: string | null
  isActive: boolean
  createdAt?: string
  updatedAt?: string
}

export interface OutletListParams {
  page: number
  limit: number
  search?: string
  isActive?: 'true' | 'false'
}

export interface OutletListResult {
  items: Outlet[]
  meta: ListMeta
}

export interface CreateOutletPayload {
  name: string
  address?: string
  phone?: string
}

export interface UpdateOutletPayload {
  name?: string
  address?: string
  phone?: string
  isActive?: boolean
}

function toQuery(params: OutletListParams): Record<string, string | number> {
  const query: Record<string, string | number> = { page: params.page, limit: params.limit }
  if (params.search) {
    query.search = params.search
  }
  if (params.isActive !== undefined) {
    query.isActive = params.isActive
  }
  return query
}

export const outletService = {
  async list(params: OutletListParams): Promise<OutletListResult> {
    const response = await httpClient.get<ApiListResponse<Outlet>>('/outlets', {
      params: toQuery(params),
    })
    return { items: response.data.data, meta: response.data.meta }
  },

  async create(payload: CreateOutletPayload): Promise<Outlet> {
    const response = await httpClient.post<ApiSuccess<Outlet>>('/outlets', payload)
    return response.data.data
  },

  async update(id: string, payload: UpdateOutletPayload): Promise<Outlet> {
    const response = await httpClient.put<ApiSuccess<Outlet>>(`/outlets/${id}`, payload)
    return response.data.data
  },

  async remove(id: string): Promise<void> {
    await httpClient.delete<ApiSuccess<null>>(`/outlets/${id}`)
  },
}
